"""Auto-generated file GraphQL query and mutation resolvers."""

from __future__ import annotations

from strawberry import Info
from strawberry.relay import PageInfo

from ai.backend.common.contexts.user import current_user
from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
    ScopedSearchAutoGeneratedFilesInput,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.response import (
    SearchAutoGeneratedFilesPayload,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.types import AutoGeneratedFileScope
from ai.backend.common.dto.manager.v2.rbac.types import UUIDScope
from ai.backend.common.meta.meta import NEXT_RELEASE_VERSION
from ai.backend.manager.api.gql.auto_generated_file.types import (
    AutoGeneratedFileConnectionGQL,
    AutoGeneratedFileEdgeGQL,
    AutoGeneratedFileFilterGQL,
    AutoGeneratedFileGQL,
    AutoGeneratedFileOrderByGQL,
    AutoGeneratedFileScopeGQL,
    CreateAutoGeneratedFileInputGQL,
    CreateAutoGeneratedFilePayloadGQL,
    PurgeAutoGeneratedFileInputGQL,
    PurgeAutoGeneratedFilePayloadGQL,
    SwitchDefaultAutoGeneratedFileInputGQL,
    SwitchDefaultAutoGeneratedFilePayloadGQL,
)
from ai.backend.manager.api.gql.base import encode_cursor, to_global_id
from ai.backend.manager.api.gql.decorators import (
    BackendAIGQLMeta,
    gql_mutation,
    gql_root_field,
)
from ai.backend.manager.api.gql.types import StrawberryGQLContext
from ai.backend.manager.errors.auth import InsufficientPrivilege


@gql_root_field(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description=(
            "Page through the auto-generated files of the named domains, projects and users, "
            "combined with OR. Every scope is authorized before the read runs."
        ),
    )
)
async def scoped_auto_generated_files(
    info: Info[StrawberryGQLContext],
    scope: AutoGeneratedFileScopeGQL,
    filter: AutoGeneratedFileFilterGQL | None = None,
    order_by: list[AutoGeneratedFileOrderByGQL] | None = None,
    before: str | None = None,
    after: str | None = None,
    first: int | None = None,
    last: int | None = None,
    limit: int | None = None,
    offset: int | None = None,
) -> AutoGeneratedFileConnectionGQL | None:
    payload = await info.context.adapters.auto_generated_file.scoped_search(
        ScopedSearchAutoGeneratedFilesInput(
            scope=scope.to_pydantic(),
            filter=filter.to_pydantic() if filter else None,
            order=[o.to_pydantic() for o in order_by] if order_by else None,
            first=first,
            after=after,
            last=last,
            before=before,
            limit=limit,
            offset=offset,
        )
    )
    return build_auto_generated_file_connection(payload)


@gql_root_field(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description="Page through the current user's own auto-generated files.",
    )
)
async def my_auto_generated_files(
    info: Info[StrawberryGQLContext],
    filter: AutoGeneratedFileFilterGQL | None = None,
    order_by: list[AutoGeneratedFileOrderByGQL] | None = None,
    before: str | None = None,
    after: str | None = None,
    first: int | None = None,
    last: int | None = None,
    limit: int | None = None,
    offset: int | None = None,
) -> AutoGeneratedFileConnectionGQL | None:
    me = current_user()
    if me is None:
        raise InsufficientPrivilege("Authentication required")
    payload = await info.context.adapters.auto_generated_file.scoped_search(
        ScopedSearchAutoGeneratedFilesInput(
            scope=AutoGeneratedFileScope(user=[UUIDScope(value=me.user_id)]),
            filter=filter.to_pydantic() if filter else None,
            order=[o.to_pydantic() for o in order_by] if order_by else None,
            first=first,
            after=after,
            last=last,
            before=before,
            limit=limit,
            offset=offset,
        )
    )
    return build_auto_generated_file_connection(payload)


@gql_mutation(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description=(
            "Add a file to a domain, project or user. The file is not the default of its path; "
            "make it the default with `switchDefaultAutoGeneratedFile`."
        ),
    )
)
async def create_auto_generated_file(
    info: Info[StrawberryGQLContext],
    input: CreateAutoGeneratedFileInputGQL,
) -> CreateAutoGeneratedFilePayloadGQL | None:
    payload = await info.context.adapters.auto_generated_file.create(input.to_pydantic())
    return CreateAutoGeneratedFilePayloadGQL.from_pydantic(payload)


@gql_mutation(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description=(
            "Make a file the default of its path in its scope. The previous default stays as a "
            "file that is not the default."
        ),
    )
)
async def switch_default_auto_generated_file(
    info: Info[StrawberryGQLContext],
    input: SwitchDefaultAutoGeneratedFileInputGQL,
) -> SwitchDefaultAutoGeneratedFilePayloadGQL | None:
    payload = await info.context.adapters.auto_generated_file.switch_default(input.to_pydantic())
    return SwitchDefaultAutoGeneratedFilePayloadGQL.from_pydantic(payload)


@gql_mutation(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description=(
            "Remove a file that is not the default of its path. The default is refused; "
            "switch the default to another file first."
        ),
    )
)
async def purge_auto_generated_file(
    info: Info[StrawberryGQLContext],
    input: PurgeAutoGeneratedFileInputGQL,
) -> PurgeAutoGeneratedFilePayloadGQL | None:
    payload = await info.context.adapters.auto_generated_file.purge(input.to_pydantic())
    return PurgeAutoGeneratedFilePayloadGQL.from_pydantic(
        payload, extra={"purged_id": to_global_id(AutoGeneratedFileGQL, payload.entity_id)}
    )


def build_auto_generated_file_connection(
    payload: SearchAutoGeneratedFilesPayload,
) -> AutoGeneratedFileConnectionGQL:
    nodes = [AutoGeneratedFileGQL.from_pydantic(item) for item in payload.items]
    edges = [
        AutoGeneratedFileEdgeGQL(node=node, cursor=encode_cursor(str(node.id))) for node in nodes
    ]
    return AutoGeneratedFileConnectionGQL(
        edges=edges,
        page_info=PageInfo(
            has_next_page=payload.has_next_page,
            has_previous_page=payload.has_previous_page,
            start_cursor=edges[0].cursor if edges else None,
            end_cursor=edges[-1].cursor if edges else None,
        ),
        count=payload.total_count,
    )
